"use client";

// Gold strategies v2 (22 Nov 2026): the owner's list of 20 YouTube channels for gold (numbers 21-40), their gold videos
// read in full, the strategies found in them with their rules (E stated / I inferred / A our assumption, each stated rule
// with its quote and video time), what was not coded and why, and every video read. Data: ./goldYtData.ts, generated by
// backend/research/youtube_gold_2026_11/zg_export.py. The coded strategies paper trade on the desk (source youtube_gold,
// Rs 10 lakh each, simulated orders on Delta Exchange's XAUTUSD candles); each card shows its account through
// ShortlistPaper. Paper only: nothing here can place an order.
import { useMemo, useState } from "react";
import GlassPanel from "../../components/GlassPanel";
import type { Account, Summary } from "./PaperDesk";
import { SEG_PLACE, type SegFocus, type SegId } from "./Segments";
import ShortlistPaper, { type ShortlistBook } from "./ShortlistPaper";
import { GY, GY_CHANNELS, GY_META, GY_NOT, type GyRule, type GyStrategy, type GyTime } from "./goldYtData";

const STUDY = "youtube_gold";
type OpenFn = (f: Omit<SegFocus, "at">) => void;
type Book = ShortlistBook & { segment?: string };
const isSeg = (s?: string): s is SegId => !!s && s in SEG_PLACE;
const TITLE = Object.fromEntries(GY_CHANNELS.flatMap((c) => c.videos.map((v) => [v.id, v.title]))) as Record<string, string>;
const STATUS: Record<string, { label: string; cls: string }> = {
  blocked: { label: "Needs data or tools the desk lacks", cls: "bad" },
  duplicate: { label: "Repeats a coded strategy", cls: "idle" },
  concept: { label: "No testable rule", cls: "idle" },
};

function sec(t: string): number {
  const p = t.split(":").map(Number);
  return p.length === 3 ? p[0] * 3600 + p[1] * 60 + p[2] : p[0] * 60 + p[1];
}

const istTime = (iso: string) =>
  new Date(iso).toLocaleString("en-IN", { timeZone: "Asia/Kolkata", dateStyle: "medium", timeStyle: "short" });

/** Video times as links that open the video at that second; a time in another video carries that video's title. */
function Times({ main, times }: { main: string; times: (GyTime | null)[] }) {
  const ts = times.filter((t): t is GyTime => !!t);
  if (!ts.length) return null;
  return (
    <span className="gyt-times">
      {ts.map((t, i) => (
        <a key={`${t.v}-${t.t}-${i}`} href={`https://youtu.be/${t.v}?t=${sec(t.t)}`} target="_blank" rel="noreferrer">
          {t.v === main ? t.t : `${TITLE[t.v] ?? t.v} ${t.t}`}
        </a>
      ))}
    </span>
  );
}

function grouped(rules: GyRule[]): [string, GyRule[]][] {
  const out: [string, GyRule[]][] = [];
  for (const r of rules) {
    const last = out[out.length - 1];
    if (last && last[0] === r.label) last[1].push(r);
    else out.push([r.label, [r]]);
  }
  return out;
}

function Card({ s, account, books, onOpen }: { s: GyStrategy; account?: Account; books?: Book[]; onOpen?: OpenFn }) {
  const stated = s.rules.filter((r) => r.tag !== "A");
  const ours = s.rules.filter((r) => r.tag === "A");
  const segs = Array.from(new Set((books ?? []).map((b) => b.segment).filter(isSeg)));
  return (
    <div className="ps-card gyt-card">
      <div className="ps-card-top">
        <span className="ps-fam up">{s.id} · {s.version}</span>
        <span className="gyt-dim">{s.channel}</span>
      </div>
      <div className="ps-card-name">{s.name}</div>
      <div className="gyt-line">{s.market} · {s.timeframes.join(", ")} · {s.overnight ? "swing (may hold overnight)" : "intraday"}</div>
      <div className="gyt-line">
        Source video: <a href={`https://youtu.be/${s.video}`} target="_blank" rel="noreferrer">{s.title || s.video}</a>
        <span className="gyt-dim">{s.uploaded ? ` · ${s.uploaded}` : ""}{s.minutes ? ` · ${s.minutes} min` : ""}</span>
      </div>
      {s.cites.length > 0 && (
        <div className="gyt-line gyt-dim">
          {"Also from: "}
          {s.cites.map((c, i) => (
            <span key={c.v}>{i ? " · " : ""}<a href={`https://youtu.be/${c.v}`} target="_blank" rel="noreferrer">{c.title || c.v}</a></span>
          ))}
        </div>
      )}
      <p className="gyt-sum">{s.summary}</p>
      <div className="gyt-tags">
        <span className={`gyt-tag ${s.readiness === "ready" ? "ok" : "warn"}`}>{s.readiness === "ready" ? "Every rule stated" : "Coded with documented assumptions"}</span>
        <span className={`gyt-tag ${s.checks.lookahead && s.checks.fills ? "ok" : "bad"}`}>
          {s.checks.lookahead && s.checks.fills ? "Look-ahead and fill checks passed" : "Code check failed"}
        </span>
        <span className="gyt-tag">Not backtested</span>
      </div>
      <ShortlistPaper status="coded" account={account} books={books} start={s.paperStart ?? GY_META.paperStart} />
      {onOpen && segs.length > 0 && (
        <div className="gyt-open">
          {segs.map((g) => {
            const b = (books ?? []).find((x) => x.segment === g);
            return (
              <button key={g} className="gyt-openbtn" onClick={() => onOpen({ seg: g, study: STUDY, book: b ? `${s.id}|${b.mkt}` : undefined })}>
                {`Open in ${SEG_PLACE[g].label} →`}
              </button>
            );
          })}
        </div>
      )}
      <details className="gyt-sec">
        <summary>{`Rules from the videos (${stated.length})`}</summary>
        {grouped(stated).map(([label, rs]) => (
          <div key={label} className="gyt-group">
            <div className="gyt-glabel">{label}</div>
            <ul className="gyt-rules">
              {rs.map((r, i) => (
                <li key={i}>
                  <span className={`gyt-t ${r.tag}`}>{r.tag}</span> {r.text} <Times main={s.video} times={r.times} />
                  {r.quote ? <span className="gyt-quote">{` “${r.quote}”`}</span> : null}
                </li>
              ))}
            </ul>
          </div>
        ))}
        <p className="gyt-dim">{"E = stated in the video · I = inferred from the speaker's words · quotes are the captions as saved (auto-captions keep their mistakes; Hindi in Latin letters)."}</p>
      </details>
      {ours.length > 0 && (
        <details className="gyt-sec">
          <summary>{`Our assumptions used to code it (${ours.length})`}</summary>
          <ul className="gyt-rules">
            {ours.map((r, i) => <li key={i}><span className="gyt-t A">A</span> <b>{r.label}:</b> {r.text}</li>)}
          </ul>
          <p className="gyt-dim">{"These are the research team's choices, not the creator's words: they fill the gaps the video leaves so the rule can run."}</p>
        </details>
      )}
      {(s.vague.length > 0 || s.claims.length > 0) && (
        <details className="gyt-sec">
          <summary>{`Vague in the video, and claims made (${s.vague.length + s.claims.length})`}</summary>
          <ul className="gyt-rules">
            {s.vague.map((v, i) => (
              <li key={`v${i}`}>{`“${v.term}”`} <Times main={s.video} times={[v.at]} />{`: ${v.why}. Coded as: ${v.coded}.`}</li>
            ))}
            {s.claims.map((c, i) => <li key={`c${i}`}>{`Claim: ${c.value}`} <Times main={s.video} times={[c.at]} /></li>)}
          </ul>
          <p className="gyt-dim">Claims are quoted as said and not verified.</p>
        </details>
      )}
      <div className="gyt-dim">{`Not a duplicate: ${s.duplicateCheck}.`}</div>
      <div className="gyt-dim">{`Code check on research data: ${s.checks.signals} signals, ${s.checks.trades} simulated fills (a correctness check, not a result).`}</div>
    </div>
  );
}

export default function GoldYt({ summary, onOpen }: { summary: Summary | null; error?: string | null; onOpen?: OpenFn }) {
  const byId = useMemo(() => Object.fromEntries((summary?.accounts ?? []).map((a) => [a.id, a])) as Record<string, Account>, [summary]);
  const booksById = ((summary?.status as { books?: Record<string, Book[]> } | undefined)?.books ?? {});
  const [chan, setChan] = useState<string>("all");
  const m = GY_META;
  const onDesk = GY.filter((s) => byId[s.id]).length;
  const shown = chan === "all" ? GY : GY.filter((s) => s.channel === chan);
  const chans = Array.from(new Set(GY.map((s) => s.channel)));
  return (
    <>
      <GlassPanel title="Gold strategies v2 — 20 YouTube channels (21–40)" note={`${m.coded} coded · paper trading · ₹10 lakh each`}>
        <p className="gyt-intro">
          {`The owner's second list of ${m.channels} gold channels (numbers 21–40). ${m.read} of their gold videos were read in full from their captions (one more was a live stream that had not aired). `}
          {`They hold ${m.coded} strategies clear enough to code, each written as exact rules (version v1) with every stated rule linked to its moment in the video and every gap we filled marked as our assumption. `}
          {`${m.notCoded} more methods have no account: ${m.blocked} need data or paid tools the desk does not have (order-book, footprint and delta reading, the CFTC report, closed indicators), ${m.duplicates} repeat a coded one and ${m.concept} teach no testable rule. `}
          {`All ${m.checked} coded strategies passed the look-ahead and fill checks; none is backtested. Each paper trades its own ₹10 lakh account on Delta Exchange's XAUTUSD 1-minute candles from ${istTime(m.paperStart)} IST (the gold week that opens Sunday 17:00 New York), flat at the start, risking 1% of its equity a trade, net of Delta's fee, the spread and slippage. No real order is ever placed.`}
          {summary ? ` ${onDesk} of ${m.coded} accounts are on the desk.` : ""}
        </p>
      </GlassPanel>
      <div className="ps-chips gyt-chips">
        <button className={`ps-chip${chan === "all" ? " on" : ""}`} onClick={() => setChan("all")}>{`All · ${GY.length}`}</button>
        {chans.map((c) => (
          <button key={c} className={`ps-chip${chan === c ? " on" : ""}`} onClick={() => setChan(c)}>
            {`${c} · ${GY.filter((s) => s.channel === c).length}`}
          </button>
        ))}
      </div>
      <div className="ps-cards gyt-cards">
        {shown.map((s) => <Card key={s.id} s={s} account={byId[s.id]} books={booksById[s.id]} onOpen={onOpen} />)}
      </div>
      <GlassPanel title="Methods without an account" note="data the desk lacks, paid tools, repeats, or no testable rule">
        <ul className="gyt-list">
          {GY_NOT.map((x) => (
            <li key={x.id}>
              <b>{`${x.id} ${x.name}`}</b> <span className="gyt-dim">({x.channel})</span>{" "}
              <span className={`gyt-pill ${STATUS[x.status]?.cls ?? "idle"}`}>{STATUS[x.status]?.label ?? x.status}</span>
              {` ${x.reason}${x.duplicateOf ? ` (see ${x.duplicateOf})` : ""}. `}
              {x.videos.map((v, i) => (
                <span key={v.v}>{i ? " · " : ""}<a href={`https://youtu.be/${v.v}`} target="_blank" rel="noreferrer">{v.title || v.v}</a></span>
              ))}
            </li>
          ))}
        </ul>
      </GlassPanel>
      <details className="gyt-sec gyt-wide">
        <summary>{`The 20 channels and every video read (${m.videos})`}</summary>
        <table className="gyt-table">
          <thead><tr><th>#</th><th>Channel</th><th>Video</th><th>Date</th><th>Min</th><th>What it gave</th></tr></thead>
          <tbody>
            {GY_CHANNELS.flatMap((c) => c.videos.map((v, i) => (
              <tr key={v.id}>
                <td>{c.pos}</td>
                <td>
                  <a href={`https://www.youtube.com/channel/${c.channelId}`} target="_blank" rel="noreferrer">{c.name}</a>
                  {i === 0 && c.coded.length > 0 ? <span className="gyt-dim">{` · coded ${c.coded.join(", ")}`}</span> : null}
                </td>
                <td><a href={`https://youtu.be/${v.id}`} target="_blank" rel="noreferrer">{v.title || v.id}</a></td>
                <td>{v.uploaded || "—"}</td>
                <td>{v.minutes || "—"}</td>
                <td>{v.what}{v.captions ? "" : " (no captions)"}</td>
              </tr>
            )))}
          </tbody>
        </table>
        <p className="gyt-dim">Channels already in earlier studies were read again only for gold videos they had not analysed before.</p>
      </details>
      {/* global: the cards are child components; every selector is gyt-prefixed, so nothing outside this section is touched. */}
      <style jsx global>{`
        .gyt-intro { font-size: 13px; line-height: 1.6; color: var(--text-muted); margin: 0; }
        .gyt-chips { margin-top: 12px; }
        .gyt-cards { align-items: start; margin: 12px 0 16px; }
        .gyt-line { font-size: 12.5px; line-height: 1.5; overflow-wrap: anywhere; }
        .gyt-dim { color: var(--text-muted); font-size: 11.5px; }
        .gyt-sum { font-size: 12.5px; line-height: 1.55; margin: 0; color: var(--text-secondary); }
        .gyt-tags { display: flex; flex-wrap: wrap; gap: 6px; }
        .gyt-tag { font-size: 11px; padding: 2px 8px; border-radius: 999px; border: 1px solid var(--panel-border); color: var(--text-muted); }
        .gyt-tag.ok { border-color: var(--gain); color: var(--gain); }
        .gyt-tag.warn { border-color: var(--warn-border); color: var(--warn); }
        .gyt-tag.bad { border-color: var(--loss); color: var(--loss); }
        .gyt-pill { font-size: 10.5px; padding: 1px 7px; border-radius: 999px; border: 1px solid var(--panel-border); color: var(--text-muted); white-space: nowrap; }
        .gyt-pill.bad { border-color: var(--loss); color: var(--loss); }
        .gyt-open { display: flex; flex-wrap: wrap; gap: 6px; }
        .gyt-openbtn { font-size: 11.5px; padding: 3px 10px; border-radius: 999px; border: 1px solid var(--panel-border);
          background: transparent; color: var(--purple); cursor: pointer; }
        .gyt-sec { font-size: 12.5px; }
        .gyt-sec summary { cursor: pointer; font-weight: 600; }
        .gyt-wide { margin: 8px 0 16px; }
        .gyt-group { margin-top: 6px; }
        .gyt-glabel { font-size: 11px; font-weight: 800; letter-spacing: 0.04em; text-transform: uppercase; color: var(--text-muted); }
        .gyt-rules { margin: 4px 0 6px; padding-left: 18px; line-height: 1.55; }
        .gyt-rules li { margin-bottom: 4px; overflow-wrap: anywhere; }
        .gyt-quote { color: var(--text-muted); font-style: italic; font-size: 11.5px; }
        .gyt-t { display: inline-block; min-width: 16px; text-align: center; font-size: 10px; font-weight: 800; border-radius: 4px; padding: 0 3px;
          border: 1px solid var(--panel-border); color: var(--text-muted); }
        .gyt-t.E { border-color: var(--gain); color: var(--gain); }
        .gyt-t.I { border-color: var(--purple); color: var(--purple); }
        .gyt-t.A { border-color: var(--warn-border); color: var(--warn); }
        .gyt-times a { margin-left: 6px; font-size: 11px; font-variant-numeric: tabular-nums; }
        .gyt-list { font-size: 12.5px; line-height: 1.6; padding-left: 18px; margin: 0; }
        .gyt-list li { margin-bottom: 8px; overflow-wrap: anywhere; }
        .gyt-table { width: 100%; border-collapse: collapse; font-size: 12px; margin-top: 8px; }
        .gyt-table th, .gyt-table td { text-align: left; padding: 4px 6px; border-bottom: 1px solid var(--panel-border); vertical-align: top; }
        @media (max-width: 640px) { .gyt-table { display: block; overflow-x: auto; } }
      `}</style>
    </>
  );
}
